var t=[{title:`Vyberte opakovatelné měření`,text:`Dobrými možnostmi jsou, jak daleko ujdete za stanovený čas, jak dlouho trvá známá trasa, zda dokončíte stanovený intervalový trénink, nebo vaše tepová frekvence při pohodlném pevném tempu. RPE tréninku tato čísla doplňuje, zejména pokud nemáte měřič tepu.`},{title:`Držte podmínky testu podobné`,text:`Teplota, kopce, spánek, kofein, vybavení a regenerace všechno ovlivňují výkon. Když můžete, porovnávejte stejné nastavení běžeckého pásu, odpor kola nebo venkovní trasu. Nižší tepová frekvence nemusí vždy znamenat, že jste fit, protože údaj může změnit i léky a chyba měření.`},{title:`Příklad`,text:`Začátečník začíná střídáním dvou minut chůze s jednou minutou jemného joggingu. O týdny později dokončí víc joggingových intervalů při podobném úsilí. Někdo jiný jede stejnou trasu na kole a připadá mu snazší, i když průměrná rychlost zůstává stejná.`},{title:`Jak často testovat`,text:`Plánovaná kontrola jednou za několik týdnů ukazuje trendy, zatímco vaše běžné tréninky zůstávají zaměřené na trénink. Náhlý pokles výkonu může pocházet z únavy nebo nemoci a nemusí znamenat, že jste kondici ztratili nadobro.`},{title:`Použití v TrainUp`,text:`Po každém tréninku ohodnotíte úsilí od 1 do 10 a Historie ukazuje vaše průměrné úsilí a graf za 4 týdny. Dívejte se na trend v průběhu týdnů. Jediné číslo tepové frekvence nebo rychlosti nemůže diagnostikovat zdraví vašeho oběhového systému ani ho zaručit.`}];var o=[{label:`NHS: chůze pro zdraví`,url:`https://www.nhs.uk/live-well/exercise/walking-for-health/`},{label:`Stanovisko ACSM z roku 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var a={sections:t,sources:o};export{a as default,t as sections,o as sources};